import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"reg矢量计算","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_vector_compute"},{"text":"矢量计算的搬出","link":"/api/SIMD-API/tensor_api/reg_vector_compute/vector_compute_store/vector_compute_store"},{"text":"copy（Unified Buffer到Global Memory高维切分数据搬运）","link":"/api/SIMD-API/tensor_api/reg_vector_compute/vector_compute_store/copy_ub_to_gm"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/reg_vector_compute/vector_compute_store/copy_ub_to_gm.md","filePath":"api/SIMD-API/tensor_api/reg_vector_compute/vector_compute_store/copy_ub_to_gm.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":3,"title":"搬运参数推导","slug":"搬运参数推导","link":"#搬运参数推导"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"关键特性说明","slug":"关键特性说明","link":"#关键特性说明"},{"level":3,"title":"非对齐搬出","slug":"非对齐搬出","link":"#非对齐搬出"},{"level":3,"title":"L2 Cache模式","slug":"L2-Cache模式","link":"#L2-Cache模式"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788319986000}'),c={name:"api/SIMD-API/tensor_api/reg_vector_compute/vector_compute_store/copy_ub_to_gm.md"};function t(e,s,o,d,i,r){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>copy（Unified Buffer到Global Memory的数据搬运）</h1><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>本接口为试验接口，在后续版本中可能会调整或改进，不保证后续兼容性。请开发者在使用过程中关注后续版本更新。</p></div><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>tensor_api/tensor.h</code>，命名空间为<code>asc::te</code>。</p><p>该接口用于将Unified Buffer（UB）中的数据搬运到Global Memory。接口根据源、目的Tensor的存储位置自动选择<code>copy_ub_to_gm</code>通路，并根据源、目的Layout推导搬运块数、单块长度、源步长和目的步长，支持单块长度非32字节对齐的数据搬运。</p><p>当前支持ND2ND、DN2DN和NZ2NZ搬运，不支持ZN2ZN以及不同Layout Pattern之间的格式转换。搬运过程中不执行数据类型转换，数据格式和有效内容保持不变。接口支持整Tensor搬运和通过坐标、Shape指定的局部区域搬运。Global Memory目的Tensor设置的L2 Cache Hint会传递给搬运指令。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">DstTensor</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">SrcTensor</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">copy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">DstTensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">SrcTensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">)</span>

<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">Atom</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">DstTensor</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">SrcTensor</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">copy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">copy_atom</span><span class="o">&lt;</span><span class="n">Atom</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">atom</span><span class="p">,</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">DstTensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">SrcTensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">)</span>

<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">DstTensor</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">SrcTensor</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">DstCoord</span><span class="p">,</span>
<span class="w">    </span><span class="k">typename</span><span class="w"> </span><span class="nc">SrcCoord</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">CopyShape</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">copy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">DstTensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">SrcTensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">DstCoord</span><span class="o">&amp;</span><span class="w"> </span><span class="n">dst_coord</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">SrcCoord</span><span class="o">&amp;</span><span class="w"> </span><span class="n">src_coord</span><span class="p">,</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">CopyShape</span><span class="o">&amp;</span><span class="w"> </span><span class="n">copy_shape</span><span class="p">)</span>

<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">CopyOperation</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="k">auto</span><span class="w"> </span><span class="n">make_copy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">CopyOperation</span><span class="o">&amp;</span><span class="w"> </span><span class="n">operation</span><span class="p">)</span>

<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">CopyOperation</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">CopyTrait</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="k">auto</span><span class="w"> </span><span class="n">make_copy</span><span class="p">(</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">CopyOperation</span><span class="o">&amp;</span><span class="w"> </span><span class="n">operation</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">CopyTrait</span><span class="o">&amp;</span><span class="w"> </span><span class="n">trait</span><span class="p">)</span>
</code></pre></div><p>UB到Global Memory通路使用<code>copy_ub_to_gm{}</code>作为搬运操作对象，默认trait为<code>ub_to_gm_trait_default{}</code>。</p><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><table><thead><tr><th align="left">参数名</th><th align="center">输入/输出</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">atom</td><td align="center">输入</td><td align="left">搬运原子对象，可通过<code>make_copy(copy_ub_to_gm{})</code>或<code>make_copy(copy_ub_to_gm{}, ub_to_gm_trait_default{})</code>构造。</td></tr><tr><td align="left">dst</td><td align="center">输出</td><td align="left">目的Tensor，存储位置必须为<code>location::gm</code>。目的Tensor的Cache Hint用于选择底层L2 Cache模式。</td></tr><tr><td align="left">src</td><td align="center">输入</td><td align="left">源Tensor，存储位置必须为<code>location::ub</code>。</td></tr><tr><td align="left">dst_coord</td><td align="center">输入</td><td align="left">目的区域起始坐标。显式坐标的结构应与<code>copy_shape</code>一致，也可以使用<code>zero_coord</code>。</td></tr><tr><td align="left">src_coord</td><td align="center">输入</td><td align="left">源区域起始坐标。显式坐标的结构应与<code>copy_shape</code>一致，也可以使用<code>zero_coord</code>。</td></tr><tr><td align="left">copy_shape</td><td align="center">输入</td><td align="left">搬运区域的逻辑Shape。接口根据该Shape及源、目的Layout推导起始地址和搬运参数。</td></tr></tbody></table><h3 id="搬运参数推导">搬运参数推导<a class="header-anchor" href="#搬运参数推导">​</a></h3><p><code>copy</code>根据源、目的Tensor的Layout自动推导<code>blockCount</code>、<code>blockLen</code>、源步长和目的步长。Tensor API中的单块长度和步长均以字节为单位，步长表示相邻数据块起始地址的间隔。</p><p>对于整Tensor搬运，各Layout模式的推导规则如下：</p><table><thead><tr><th align="left">Layout模式</th><th align="left">搬运块数</th><th align="left">单块长度</th><th align="left">源、目的步长</th></tr></thead><tbody><tr><td align="left">ND</td><td align="left">源Layout的总行数</td><td align="left">源、目的Layout总列字节数的较小值</td><td align="left">对应Tensor的行步长 × 元素字节数</td></tr><tr><td align="left">DN</td><td align="left">源Layout的总列数</td><td align="left">源、目的Layout总行字节数的较小值</td><td align="left">对应Tensor的列步长 × 元素字节数</td></tr><tr><td align="left">NZ</td><td align="left">分形格式的外层列数</td><td align="left">总行数 × 内层列数 × 元素字节数</td><td align="left">对应Tensor的外层列步长 × 元素字节数</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p>源Tensor和目的Tensor的数据类型必须相同。</p><table><thead><tr><th align="left">源/目的Layout</th><th align="left">支持的数据类型</th></tr></thead><tbody><tr><td align="left">ND、DN、NZ</td><td align="left"><code>fp4x2_e1m2_t</code>、<code>fp4x2_e2m1_t</code>、<code>int8_t</code>、<code>uint8_t</code>、<code>hifloat8_t</code>、<code>fp8_e5m2_t</code>、<code>fp8_e4m3fn_t</code>、<code>int16_t</code>、<code>uint16_t</code>、<code>half</code>、<code>bfloat16_t</code>、<code>int32_t</code>、<code>uint32_t</code>、<code>float</code>、<code>int64_t</code></td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p><code>copy</code>无返回值。<code>make_copy</code>返回<code>copy_atom</code>对象。</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>源Tensor必须位于UB，目的Tensor必须位于Global Memory。</li><li>源UB地址需满足32字节对齐要求，目的Global Memory地址支持1字节对齐。</li><li>源、目的Layout Pattern必须相同。当前支持ND2ND、DN2DN和NZ2NZ、ZN2ZN。</li><li>源、目的数据类型必须相同，目的Tensor或目的区域容量必须不小于搬运区域。</li><li>Layout推导出的搬运块数、单块长度和步长必须满足底层<code>asc_copy_ub2gm_align</code>指令的字段范围及对齐要求。有效搬运的块数取值范围为[1, 4095]，单块长度取值范围为[1, 2097151]字节，且单块长度必须为元素字节数的整数倍。</li><li>有效搬运的源步长必须等于单块长度，或为32字节的正整数倍。前者表示UB中的数据块紧凑排列，后者表示各数据块按32字节边界排列。</li><li>与部分产品上的<code>DataCopyExtParams</code>接口不同，Tensor API要求源、目的Layout以及区域搬运Shape合法，不能依赖搬运块数或单块长度为0表示空操作。</li><li>b4类型按b8搬运粒度调整块长度和步长。</li></ul><h2 id="关键特性说明">关键特性说明<a class="header-anchor" href="#关键特性说明">​</a></h2><h3 id="非对齐搬出">非对齐搬出<a class="header-anchor" href="#非对齐搬出">​</a></h3><p>UB源地址按32字节对齐，Global Memory目的端允许1字节对齐。单块长度为32字节的整数倍时，块内数据全部写入Global Memory；单块长度不是32字节的整数倍时，底层指令按32字节粒度处理UB侧尾部，但只将单块长度指定的有效字节写入Global Memory，尾部补齐数据不会写入目的Tensor。</p><p>以元素类型为<code>half</code>、搬运Shape为<code>(2, 23)</code>的ND Tensor为例，单块有效长度为<code>23 × sizeof(half) = 46</code>字节：</p><table><thead><tr><th align="left">UB源Tensor行步长</th><th align="left">GM目的Tensor行步长</th><th align="left">推导结果</th><th align="left">搬运方式</th></tr></thead><tbody><tr><td align="left">32个元素（64字节）</td><td align="left">23个元素（46字节）</td><td align="left">块数为2、单块长度为46字节、源步长为64字节、目的步长为46字节</td><td align="left">UB侧每块按32字节边界排列，尾部18字节不写入GM；GM侧有效数据连续排列。</td></tr><tr><td align="left">23个元素（46字节）</td><td align="left">23个元素（46字节）</td><td align="left">块数为2、单块长度为46字节、源步长和目的步长均为46字节</td><td align="left">UB和GM中的有效数据块均紧凑排列。</td></tr></tbody></table><p>当目的步长大于单块长度时，Global Memory中相邻有效数据块之间保留<code>目的步长 - 单块长度</code>字节的间隔，该间隔不会被写入。</p><h3 id="L2-Cache模式">L2 Cache模式<a class="header-anchor" href="#L2-Cache模式">​</a></h3><p>接口从目的Global Memory Tensor的Engine中取得Cache Hint，并转换为底层<code>asc_store_l2_cache_mode</code>参数。需要指定Cache策略时，应在目的Tensor上设置对应Hint，无需向<code>copy</code>额外传参。</p><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/tensor.h&quot;</span>

<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">M</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">N</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">64</span><span class="p">;</span>

<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">copy_ub_to_gm_example</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">gm_addr</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">ub_buf</span><span class="p">[</span><span class="n">M</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">N</span><span class="p">];</span>

<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">layout</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">nd_ext_layout_ptn</span><span class="p">,</span>
<span class="w">        </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">layout_trait_default</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;&gt;</span><span class="p">(</span><span class="n">M</span><span class="p">,</span><span class="w"> </span><span class="n">N</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">src</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_tensor</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_mem_ptr</span><span class="o">&lt;</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">location</span><span class="o">::</span><span class="n">ub</span><span class="o">&gt;</span><span class="p">(</span><span class="n">ub_buf</span><span class="p">),</span><span class="w"> </span><span class="n">layout</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">dst</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_tensor</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_mem_ptr</span><span class="o">&lt;</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">location</span><span class="o">::</span><span class="n">gm</span><span class="o">&gt;</span><span class="p">(</span><span class="n">gm_addr</span><span class="p">),</span><span class="w"> </span><span class="n">layout</span><span class="p">);</span>

<span class="w">    </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">copy</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">src</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><p>该示例的ND Layout包含8行，每行64个<code>half</code>元素，因此接口推导出块数为8、单块长度为128字节，源步长和目的步长均为128字节。单块长度满足32字节对齐要求，UB和GM中的数据块均连续排列。</p><p>以下示例显式构造搬运原子对象，并搬运单块长度非32字节对齐的局部区域：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">auto</span><span class="w"> </span><span class="n">atom</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_copy</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">copy_ub_to_gm</span><span class="p">{},</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">ub_to_gm_trait_default</span><span class="p">{});</span>
<span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">copy</span><span class="p">(</span><span class="n">atom</span><span class="p">,</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">),</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">),</span>
<span class="w">    </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_shape</span><span class="p">(</span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">23</span><span class="p">));</span>
</code></pre></div><p>该区域包含2行，每行搬运23个<code>half</code>元素，因此接口推导出块数为2、单块长度为46字节。源、目的Tensor的行步长均为128字节，所以源步长和目的步长均为128字节。每块仅有46字节有效数据写入GM，UB侧尾部补齐数据不会写入；GM中相邻有效数据块之间保留82字节间隔。</p></article></div>`,1)])])}const w=a(c,[["render",t]]);export{h as __pageData,w as default};
